### Issue A Fix: Prevent spurious auto-resume during phone calls

**Current problematic code in PlaybackSessionController.swift:385-396:**
```swift
if !currentHasPhoneRoute && interruptionContext != nil {
    if let context = interruptionContext, context.shouldAutoResume {
        os_log(.info, log: logger, "📞 Interruption ended via route change - auto-resuming")
        interruptionContext = nil
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.6) { [weak self] in
            self?.slimProtoProvider?()?.sendLockScreenCommand("play")
        }
    }
}
```

**Fix implementation:**
1. Add a new property to track if interruption has formally ended:
```swift
private var interruptionHasEnded = false
```

2. In `handleInterruption` case `.ended`, set `interruptionHasEnded = true`

3. Modify the route change auto-resume logic to REQUIRE `interruptionHasEnded`:
```swift
if !currentHasPhoneRoute && interruptionContext != nil && interruptionHasEnded {
    // ... existing resume logic
    interruptionHasEnded = false  // Reset after use
}
```

4. Add minimum duration check - don't allow route-based resume if interrupted < 2 seconds:
```swift
if let context = interruptionContext,
   context.shouldAutoResume,
   Date().timeIntervalSince(context.beganAt) > 2.0 {
    // Safe to resume
}
```

### Issue B Fix: Confirm pause reached server after CarPlay disconnect

**Current problematic code in PlaybackSessionController.swift:446-451:**
```swift
if let coordinator = self.slimProtoProvider?() {
    coordinator.sendLockScreenCommand("pause")
}
```

**Fix implementation - add to SlimProtoCoordinator.swift:**

1. Create new method `sendPauseWithConfirmation`:
```swift
func sendPauseWithConfirmation(maxRetries: Int = 3, completion: ((Bool) -> Void)? = nil) {
    sendLockScreenCommand("pause")

    // After 1 second, verify server is paused
    DispatchQueue.main.asyncAfter(deadline: .now() + 1.0) { [weak self] in
        self?.verifyServerPaused(retriesRemaining: maxRetries, completion: completion)
    }
}

private func verifyServerPaused(retriesRemaining: Int, completion: ((Bool) -> Void)?) {
    let playerID = settings.playerMACAddress
    let statusCommand: [String: Any] = [
        "id": 1,
        "method": "slim.request",
        "params": [playerID, ["status", "-", 1, "tags:"]]
    ]

    sendJSONRPCCommandDirect(statusCommand) { [weak self] response in
        guard let self = self else { return }

        if let result = response["result"] as? [String: Any],
           let mode = result["mode"] as? String,
           mode == "pause" || mode == "stop" {
            os_log(.info, log: self.logger, "✅ Server confirmed paused")
            completion?(true)
        } else if retriesRemaining > 0 {
            os_log(.warning, log: self.logger, "⚠️ Server not paused, retrying... (%d left)", retriesRemaining)
            // Retry pause command
            self.sendLockScreenCommand("pause")
            DispatchQueue.main.asyncAfter(deadline: .now() + 1.5) {
                self.verifyServerPaused(retriesRemaining: retriesRemaining - 1, completion: completion)
            }
        } else {
            os_log(.error, log: self.logger, "❌ Failed to confirm server pause after retries")
            completion?(false)
        }
    }
}
```

2. Update `handleCarPlayDisconnected` in PlaybackSessionController.swift to use the new method:
```swift
if let coordinator = self.slimProtoProvider?() as? SlimProtoCoordinator {
    coordinator.sendPauseWithConfirmation { success in
        if !success {
            os_log(.error, log: self.logger, "❌ CarPlay disconnect pause failed after retries")
        }
    }
}
```

3. Add protocol method to SlimProtoControlling:
```swift
func sendPauseWithConfirmation(maxRetries: Int, completion: ((Bool) -> Void)?)
```

### LMS Status Response Reference
The `status` command returns:
- `mode`: "play", "pause", or "stop"
- `playlist_cur_index`: current track index
- `time`: current position in seconds

